  "diodeSpec": { enumerable: true, get: function () { return diodeSpec; } },
  "junctionCurrent": { enumerable: true, get: function () { return junctionCurrent; } },
  "junctionConductance": { enumerable: true, get: function () { return junctionConductance; } },
  "limitJunctionV": { enumerable: true, get: function () { return limitJunctionV; } },
  "ZENER_ISZ": { enumerable: true, get: function () { return ZENER_ISZ; } },
  "ZENER_NZ": { enumerable: true, get: function () { return ZENER_NZ; } },
  "zenerCurrent": { enumerable: true, get: function () { return zenerCurrent; } },
  "zenerConductance": { enumerable: true, get: function () { return zenerConductance; } },
  "LED_MODELS": { enumerable: true, get: function () { return LED_MODELS; } },
  "ledSpec": { enumerable: true, get: function () { return ledSpec; } },
  "TRANSISTOR_MODELS": { enumerable: true, get: function () { return TRANSISTOR_MODELS; } },
