  "relayStateOf": { enumerable: true, get: function () { return relayStateOf; } },
  "refreshRelayState": { enumerable: true, get: function () { return refreshRelayState; } },
  "MODELS": { enumerable: true, get: function () { return MODELS; } },
  "getModel": { enumerable: true, get: function () { return getModel; } },
  "hasModel": { enumerable: true, get: function () { return hasModel; } },
  "isSkipped": { enumerable: true, get: function () { return isSkipped; } },
  "listModelTypes": { enumerable: true, get: function () { return listModelTypes; } },
  "needsBranch": { enumerable: true, get: function () { return needsBranch; } },
  "conductsDC": { enumerable: true, get: function () { return conductsDC; } },
  "conductsTransient": { enumerable: true, get: function () { return conductsTransient; } },
