  "setProjection": { enumerable: true, get: function () { return setProjection; } },
  "setRotate": { enumerable: true, get: function () { return setRotate; } },
  "resetView": { enumerable: true, get: function () { return resetView; } },
  "zoomIn": { enumerable: true, get: function () { return zoomIn; } },
  "zoomOut": { enumerable: true, get: function () { return zoomOut; } },
  "focusOnGrid": { enumerable: true, get: function () { return focusOnGrid; } },
  "project": { enumerable: true, get: function () { return project; } },
  "unproject": { enumerable: true, get: function () { return unproject; } },
  "terminalScreenPos": { enumerable: true, get: function () { return terminalScreenPos; } },
  "componentCorners": { enumerable: true, get: function () { return componentCorners; } },
  "ensurePlatformLayer": { enumerable: true, get: function () { return ensurePlatformLayer; } },
  "invalidatePlatformLayer": { enumerable: true, get: function () { return invalidatePlatformLayer; } },
