  g.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
  g.fillStyle = SCHEM_COLORS.paper;
  g.fillRect(0, 0, view.width, view.height);

  const step = view.cell * 2;
  const startX = view.originX - Math.ceil(view.originX / step) * step;
