    const size = symSize(comp.type, comp.rotation || 0);
    const text = symbolLabel(comp);
    ctx.font = `${labelSize}px "Cascadia Mono", Consolas, monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillStyle = SCHEM_COLORS.label;
